import { Audio } from "@remotion/media";
import { interpolate, staticFile, useVideoConfig } from "remotion";
import type { Cue, Duck, Sfx } from "./timeline";

export type { Cue, Duck, Sfx };

const SFX_GAIN: Record<Sfx, number> = { whoosh: 0.32, tick: 0.22, hit: 0.3, chime: 0.26 };

// Music bed (original, generated by scripts/make_audio.py) ducked under every caption and
// callout, plus UI sounds on cues. Times are composition frames.
export const Sound: React.FC<{ bed: string; ducks: Duck[]; cues: Cue[]; level?: number; duckTo?: number }> = ({ bed, ducks, cues, level = 0.5, duckTo = 0.26 }) => {
  const { fps } = useVideoConfig();
  const volume = (f: number) => {
    let d = 0;
    for (const w of ducks) d = Math.max(d, interpolate(f, [w.from - 6, w.from + 2, w.to - 2, w.to + 8], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }));
    return level - (level - duckTo) * d;
  };
  return (
    <>
      <Audio name="Music bed" src={staticFile(bed)} volume={volume} premountFor={fps} />
      {cues.map((c, i) => (
        <Audio key={i} name={`sfx ${c.sfx}`} from={Math.max(0, Math.round(c.at))} durationInFrames={2 * fps} premountFor={fps} src={staticFile(`audio/sfx/${c.sfx}.wav`)} volume={c.volume ?? SFX_GAIN[c.sfx]} />
      ))}
    </>
  );
};
